package com.example.bmmoney.adapter;
import android.app.*;import android.graphics.Color;import android.view.*;import android.widget.*;import androidx.annotation.NonNull;import androidx.recyclerview.widget.RecyclerView;import com.example.bmmoney.R;import com.example.bmmoney.data.TransactionEntity;import java.text.*;import java.util.*;
public class TransactionAdapter extends RecyclerView.Adapter<TransactionAdapter.TransactionViewHolder>{private final List<TransactionEntity> transactions=new ArrayList<>();private final NumberFormat money=NumberFormat.getCurrencyInstance(new Locale("vi","VN"));private final SimpleDateFormat df=new SimpleDateFormat("dd/MM/yyyy",Locale.getDefault());public void setTransactions(List<TransactionEntity> list){transactions.clear();if(list!=null)transactions.addAll(list);notifyDataSetChanged();}@NonNull public TransactionViewHolder onCreateViewHolder(@NonNull ViewGroup p,int v){return new TransactionViewHolder(LayoutInflater.from(p.getContext()).inflate(R.layout.item_transaction,p,false));}public void onBindViewHolder(@NonNull TransactionViewHolder h,int pos){TransactionEntity t=transactions.get(pos);boolean income="INCOME".equals(t.getType());h.tvTitle.setText(t.getTitle());h.tvCategory.setText(t.getCategory());h.tvDate.setText(df.format(new Date(t.getDate())));h.tvAmount.setText((income?"+ ":"- ")+money.format(t.getAmount()));h.tvAmount.setTextColor(Color.parseColor(income?"#606C38":"#BC6C25"));h.tvIcon.setText(income?"↑":"↓");h.tvIcon.setBackgroundResource(income?R.drawable.bg_income:R.drawable.bg_expense);h.itemView.setOnClickListener(v->new AlertDialog.Builder(v.getContext()).setTitle(t.getTitle()).setMessage("Loại: "+(income?"Thu nhập":"Chi tiêu")+"\nDanh mục: "+t.getCategory()+"\nSố tiền: "+money.format(t.getAmount())+"\nNgày: "+df.format(new Date(t.getDate()))+"\nGhi chú: "+(t.getNote()==null||t.getNote().isEmpty()?"Không có":t.getNote())).setPositiveButton("Đóng",null).show());}public int getItemCount(){return transactions.size();}static class TransactionViewHolder extends RecyclerView.ViewHolder{TextView tvIcon,tvTitle,tvCategory,tvDate,tvAmount;TransactionViewHolder(@NonNull View v){super(v);tvIcon=v.findViewById(R.id.tvIcon);tvTitle=v.findViewById(R.id.tvTitle);tvCategory=v.findViewById(R.id.tvCategory);tvDate=v.findViewById(R.id.tvDate);tvAmount=v.findViewById(R.id.tvAmount);}}}
